try:
    await asyncio.gather(*running)
except asyncio.CancelledError:
    # Cancel any task that is still running, then wait for all of them so
    # their cleanup code (finally blocks, async with exits, ...) finishes
    # before the cancellation propagates out of run_tasks.
    for fut in running:
        fut.cancel()
    # Drive the in-flight tasks to completion. Awaiting a cancelled future
    # collection can itself be interrupted by a repeated cancellation, so
    # loop until every future is actually done, swallowing any further
    # CancelledError raised at this await point.
    pending = running
    while pending:
        try:
            await asyncio.gather(*pending, return_exceptions=True)
        except asyncio.CancelledError:
            pass
        pending = [fut for fut in pending if not fut.done()]
    raise
